import argparse, importlib.util, json, random, statistics, tempfile, time, os, hashlib, platform, shutil
from pathlib import Path
repo=Path('/Users/bhuvanprakash/j/jhol')
spec=importlib.util.spec_from_file_location('matrix',repo/'scripts/bench/paper_matrix.py')
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
inputs=json.loads((repo/'docs/architecture/experiments/cold-stage-baseline-20261003-233517.json').read_text())['fixture_inputs']
fixture_file=repo/'docs/architecture/experiments/cold-stage-baseline-20261003-233517.json'
binary=repo/'target/release/jhol'; bun=Path('/Users/bhuvanprakash/.bun/bin/bun')
if not binary.is_file(): raise SystemExit('missing release binary')
with tempfile.TemporaryDirectory(prefix='jhol-stream-ab-') as td:
 root=Path(td); fixture=root/'fixture'; fixture.mkdir()
 for name,content in inputs.items(): (fixture/name).write_text(json.dumps(content,indent=2)+'\n')
 args=argparse.Namespace(fixture=fixture,fixture_lock_sha256=m.hash_file(fixture/'package-lock.json'),condition='registry-cold',bun=str(bun),jhol=str(binary),node='node',timeout=120,drift_policy='fail')
 original=m.ARM_ENV['harvest'].copy(); samples=[]; rng=random.Random(20261004)
 try:
  for rnd in range(1,6):
   for variant in rng.sample(['staged','streamed'],2):
    m.ARM_ENV['harvest']=dict(original)
    if variant=='streamed': m.ARM_ENV['harvest']['JHOL_STREAM_EXTRACT']='1'
    s=m.run_one(args,'harvest',rnd,root,{},m.DEFAULT_MARKERS); s['variant']=variant; samples.append(s)
    print(variant,rnd,s['status'],round(s.get('elapsed_ms',0),2),s.get('stage_times_ms'),flush=True)
 finally: m.ARM_ENV['harvest']=original
 summaries={}
 for v in ['staged','streamed']:
  ss=[s for s in samples if s['variant']==v and s.get('status')=='pass']; vals=[s['elapsed_ms'] for s in ss]
  summaries[v]={'n':len(vals),'median_ms':statistics.median(vals) if vals else None,'p95_ms':sorted(vals)[max(0,__import__('math').ceil(.95*len(vals))-1)] if vals else None,'stage_medians_ms':{k:statistics.median([x.get('stage_times_ms',{}).get(k,0) for x in ss]) for k in sorted({k for x in ss for k in x.get('stage_times_ms',{})})}}
 report={'date_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'purpose':'five-round pilot comparing source release staged extraction against opt-in streamed extraction; not Bun comparison','condition':'registry-cold; fresh project and empty per-run JHOL cache; same pinned lockfile; harvest disabled; OS/registry caches not controlled','versions':{'jhol':m._version(str(binary)),'bun_control_not_run':m._version(str(bun))},'binary_sha256':m.hash_file(binary),'host':platform.platform(),'rounds':5,'fixture_inputs':inputs,'samples':samples,'summary':summaries,'runner_source':Path(__file__).read_text()}
 out=repo/'docs/architecture/experiments'/f"stream-extract-source-ab-pilot-{time.strftime('%Y%m%d-%H%M%S')}.json"; out.write_text(json.dumps(report,indent=2)+'\n'); print(out); print(json.dumps(summaries,indent=2)); raise SystemExit(0 if len(samples)==10 and all(s['status']=='pass' for s in samples) else 2)
